    "srcCode": "// SPDX-License-Identifier: MIT\npragma solidity 0.8.26;\n\n/// @title SoulboundToken (EIP-5114)\n/// @notice Non-transferable identity badges and soulbound credentials.\n/// @dev Any transfer or approval reverts; only minting and burning/revocation are permitted.\ncontract SoulboundToken {\n    // --- Errors ---\n    error NonTransferable();\n    error NotAuthorized();\n    error TokenDoesNotExist();\n    error AlreadyMinted();\n    error ZeroAddress();\n\n    // --- Events ---\n    event Issued(address indexed to, uint256 indexed tokenId, string uri);\n    event Revoked(address indexed from, uint256 indexed tokenId);\n\n    // --- State Variables ---\n    string public name;\n    string public symbol;\n    address public immutable issuer;\n\n    mapping(uint256 => address) private _owners;\n    mapping(address => uint256) private _balances;\n    mapping(uint256 => string) private _tokenURIs;\n\n    modifier onlyIssuer() {\n        if (msg.sender != issuer) revert NotAuthorized();\n        _;\n    }\n\n    constructor(string memory _name, string memory _symbol) {\n        name = _name;\n        symbol = _symbol;\n        issuer = msg.sender;\n    }\n\n    /// @notice Issue a non-transferable soulbound token to a recipient\n    function issue(address to, uint256 tokenId, string calldata uri) external onlyIssuer {\n        if (to == address(0)) revert ZeroAddress();\n        if (_owners[tokenId] != address(0)) revert AlreadyMinted();\n\n        _owners[tokenId] = to;\n        _balances[to] += 1;\n        _tokenURIs[tokenId] = uri;\n\n        emit Issued(to, tokenId, uri);\n    }\n\n    /// @notice Revoke / burn a soulbound token. Can be triggered by the issuer or token soul\n    function revoke(uint256 tokenId) external {\n        address tokenOwner = _owners[tokenId];\n        if (tokenOwner == address(0)) revert TokenDoesNotExist();\n        if (msg.sender != issuer && msg.sender != tokenOwner) revert NotAuthorized();\n\n        delete _owners[tokenId];\n        delete _tokenURIs[tokenId];\n        _balances[tokenOwner] -= 1;\n\n        emit Revoked(tokenOwner, tokenId);\n    }\n\n    /// @notice Lookup owner of a token ID\n    function ownerOf(uint256 tokenId) external view returns (address) {\n        address tokenOwner = _owners[tokenId];\n        if (tokenOwner == address(0)) revert TokenDoesNotExist();\n        return tokenOwner;\n    }\n\n    /// @notice Lookup token URI\n    function tokenURI(uint256 tokenId) external view returns (string memory) {\n        if (_owners[tokenId] == address(0)) revert TokenDoesNotExist();\n        return _tokenURIs[tokenId];\n    }\n\n    /// @notice Soulbound tokens cannot be transferred\n    function transferFrom(address, address, uint256) external pure {\n        revert NonTransferable();\n    }\n\n    /// @notice Soulbound tokens cannot be safe transferred\n    function safeTransferFrom(address, address, uint256) external pure {\n        revert NonTransferable();\n    }\n\n    /// @notice Approvals are disabled for soulbound tokens\n    function approve(address, uint256) external pure {\n        revert NonTransferable();\n    }\n\n    /// @notice Operator approvals are disabled for soulbound tokens\n    function setApprovalForAll(address, bool) external pure {\n        revert NonTransferable();\n    }\n\n    function balanceOf(address account) external view returns (uint256) {\n        if (account == address(0)) revert ZeroAddress();\n        return _balances[account];\n    }\n}\n",
    "testCode": "// SPDX-License-Identifier: MIT\npragma solidity 0.8.26;\n\nimport {Test} from \"forge-std/Test.sol\";\nimport {SoulboundToken} from \"../src/01_Tokens/SoulboundToken.sol\";\n\ncontract SoulboundTokenTest is Test {\n    SoulboundToken public sbt;\n    address public admin = address(this);\n    address public alice = address(0xA11CE);\n    address public bob = address(0xB0B);\n\n    function setUp() public {\n        sbt = new SoulboundToken(\"Identity Badge\", \"BADGE\");\n    }\n\n    function test_IssueBadge() public {\n        sbt.issue(alice, 1, \"ipfs://badge-1\");\n\n        assertEq(sbt.balanceOf(alice), 1);\n        assertEq(sbt.ownerOf(1), alice);\n        assertEq(sbt.tokenURI(1), \"ipfs://badge-1\");\n    }\n\n    function test_TransferReverts() public {\n        sbt.issue(alice, 1, \"ipfs://badge-1\");\n\n        vm.prank(alice);\n        vm.expectRevert(SoulboundToken.NonTransferable.selector);\n        sbt.transferFrom(alice, bob, 1);\n\n        vm.prank(alice);\n        vm.expectRevert(SoulboundToken.NonTransferable.selector);\n        sbt.approve(bob, 1);\n    }\n\n    function test_RevokeByIssuerOrHolder() public {\n        sbt.issue(alice, 1, \"ipfs://badge-1\");\n\n        // Alice (the holder) revokes her badge\n        vm.prank(alice);\n        sbt.revoke(1);\n\n        assertEq(sbt.balanceOf(alice), 0);\n        vm.expectRevert(SoulboundToken.TokenDoesNotExist.selector);\n        sbt.ownerOf(1);\n    }\n\n    function test_RevokeByUnauthorizedReverts() public {\n        sbt.issue(alice, 1, \"ipfs://badge-1\");\n\n        vm.prank(bob);\n        vm.expectRevert(SoulboundToken.NotAuthorized.selector);\n        sbt.revoke(1);\n    }\n}\n"
